def get_edges_from_adj(adj, n):
    edges = []
    for i in range(n):
        for j in adj[i]:
            if i < j:
                edges.append((i, j))
    return sorted(edges)

def find_all_short_cycles(adj, n, max_len=6):
    """Find all cycles of length <= max_len"""
    cycles = []
    for start in range(n):
        # BFS to find cycles
        visited = {start: -1}
        dist = {start: 0}
        queue = [start]
        idx = 0
        while idx < len(queue):
            v = queue[idx]
            idx += 1
            if dist[v] >= max_len:
                continue
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    visited[w] = v
                    queue.append(w)
                elif w != visited[v] and dist[w] < dist[v]:
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len <= max_len:
                        cycles.append(cycle_len)
    return cycles

def check_girth(adj, n, target=7):
    """Check if girth >= target"""
    for start in range(n):
        visited = {start: -1}
        dist = {start: 0}
        queue = [start]
        idx = 0
        while idx < len(queue):
            v = queue[idx]
            idx += 1
            if dist[v] >= target:
                continue
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    visited[w] = v
                    queue.append(w)
                elif w != visited[v]:
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len < target:
                        return False, cycle_len
    return True, target

